63		VotedAt        int64  `json:"voted_at"`
64	}
65	
66	// TallyResultView 是首次计票结论的查询视图；尚未计票时为 nil。
67	type TallyResultView struct {
68		ForWeight     int64 `json:"for_weight"`
69		AgainstWeight int64 `json:"against_weight"`
70		Turnout       int64 `json:"turnout"`
71		Quorum        int64 `json:"quorum"`
72		Passed        bool  `json:"passed"`
73		TalliedAt     int64 `json:"tallied_at"`
74	}
75	
76	// VoteProposalView 是一项投票提案的完整对外视图。
77	type VoteProposalView struct {
78		ID          string           `json:"id"`
79		Source      string           `json:"source"` // vote
80		State       string           `json:"state"`  // voting / passed / rejected / executed
81		Quorum      int64            `json:"quorum"`
82		StartAt     int64            `json:"start_at"`
83		Deadline    int64            `json:"deadline"`
84		TimelockEnd int64            `json:"timelock_end"`
85		Actions     []string         `json:"actions"`
86		TotalWeight int64            `json:"total_weight"`
87		Members     []MemberView     `json:"members"`
88		Ballots     []BallotView     `json:"ballots"`
89		Tally       *TallyResultView `json:"tally,omitempty"`
90	}
91	
92	// ---- 磁盘结构（JSON，版本仍为 1） ----
93	
94	type storedMember struct {
95		ID     string `json:"id"`
96		Weight int64  `json:"weight"`
97	}
98	
99	type storedDelegation struct {
100		From string `json:"from"`
101		To   string `json:"to"`
102	}
103	
104	// storedBallot 是一张已保存的票。四个字段都必须明确写出、非空且类型正确：
105	// representative 是 JSON 字符串，weight/voted_at 是 JSON 整数（int64 范围），
106	// support 必须是 JSON 布尔值。绝不能靠零值/默认值补出治理记录：
107	// 缺失或 null 的 support 不得被当作 false（反对票），缺失或 null 的
108	// voted_at 不得被当作 0（首次投票时间）。
109	//
110	// 标量字段先用 RawMessage 接住，使“字段缺失”与“显式 null/写错类型”在解码后
111	// 仍可区分：encoding/json 直接解进 bool/int64/string 时会把这三种情况都
112	// 折叠成零值。每个字段的“缺失/空值/类型不符”由 validateStoredBallot 判定。
113	type storedBallot struct {
114		Representative string `json:"representative"`
115		Weight         int64  `json:"weight"`
116		Support        bool   `json:"support"`
117		VotedAt        int64  `json:"voted_at"`
118	
119		representativeRaw json.RawMessage
120		weightRaw         json.RawMessage
121		supportRaw        json.RawMessage
122		votedAtRaw        json.RawMessage
123	}
124	
125	// ballotJSONShape 只用于解码，按保存格式的字段名逐字接住每个字段的原始 JSON。
126	type ballotJSONShape struct {
127		Representative json.RawMessage `json:"representative"`
128		Weight         json.RawMessage `json:"weight"`
129		Support        json.RawMessage `json:"support"`
130		VotedAt        json.RawMessage `json:"voted_at"`
131	}
132	
133	// UnmarshalJSON 保留字段是否出现及其原始写法（缺失为 nil、null 为 "null"），
134	// 供 validateStoredBallot 区分缺失、空值与类型不符。单个字段类型不符时这里
135	// 不返回错误（对应治理字段保持零值），以免解码器在不含提案编号/票据下标的
136	// 通用错误处提前失败；定位与判定统一交给 validateStoredBallot。
137	func (b *storedBallot) UnmarshalJSON(data []byte) error {
138		var shape ballotJSONShape
139		if err := json.Unmarshal(data, &shape); err != nil {
140			return err
141		}
142		b.representativeRaw, b.weightRaw = shape.Representative, shape.Weight
143		b.supportRaw, b.votedAtRaw = shape.Support, shape.VotedAt
144		// 仅当字段确实是目标类型时才填充治理字段；类型不符留待校验拒绝，
145		// 绝不能让错误类型悄悄落成零值并参与查询或计票。
146		fillString(shape.Representative, &b.Representative)
147		fillInt64(shape.Weight, &b.Weight)
148		fillBool(shape.Support, &b.Support)
149		fillInt64(shape.VotedAt, &b.VotedAt)
150		return nil
151	}
152	
153	// MarshalJSON 只输出四个治理字段，RawMessage 状态（仅用于入站判定）不落盘。
154	func (b storedBallot) MarshalJSON() ([]byte, error) {
155		return json.Marshal(storedBallotOut{
156			Representative: b.Representative,
157			Weight:         b.Weight,
158			Support:        b.Support,
159			VotedAt:        b.VotedAt,
160		})
161	}
162	
163	// storedBallotOut 是票据的保存形状；字段名与保存格式逐字一致。
164	type storedBallotOut struct {
165		Representative string `json:"representative"`
166		Weight         int64  `json:"weight"`
167		Support        bool   `json:"support"`
168		VotedAt        int64  `json:"voted_at"`
169	}
170	
171	// mustStoreBallot 构造一张内存中的合法票据（投票成功路径使用）。
172	// 同步填上字段原始片段，使“提交前校验”与“打开重放校验”走同一份
173	// validateStoredBallot 判定时不会把本进程新建的票据误判为字段缺失。
174	func mustStoreBallot(representative string, weight int64, support bool, votedAt int64) storedBallot {
175		repRaw, _ := json.Marshal(representative)
176		wRaw, _ := json.Marshal(weight)
177		supRaw, _ := json.Marshal(support)
178		atRaw, _ := json.Marshal(votedAt)
179		return storedBallot{
180			Representative:    representative,
181			Weight:            weight,
182			Support:           support,
183			VotedAt:           votedAt,
184			representativeRaw: repRaw,
185			weightRaw:         wRaw,
186			supportRaw:        supRaw,
187			votedAtRaw:        atRaw,
188		}
189	}
190	
191	// validateStoredBallot 严格判定一张已保存票据的四个必填字段：
192	// 任一字段未写出、显式为 null 或 JSON 类型不符（support 不接受字符串/数字，
193	// weight/voted_at 不接受字符串/小数/指数等非整数）都返回带原因的错误。
194	// 明确写出的 false 是有效反对票；窗口允许时明确写出的 0 是有效投票时间，
195	// 这两种合法值不得当成缺失。index 是票据在提案中的下标（0 起），用于定位。
196	// “缺失/空值/类型不符”的判定与计票结果、执行凭据共用同一份规则
197	// （validateRawFields），此处只补充票据的业务位置：提案编号 + 票据下标。
198	func validateStoredBallot(id string, index int, b *storedBallot) error {
199		return validateRawFields([]rawField{
200			{name: "representative", kind: scalarString, raw: b.representativeRaw},
201			{name: "weight", kind: scalarInteger, raw: b.weightRaw},
202			{name: "support", kind: scalarBoolean, raw: b.supportRaw},
203			{name: "voted_at", kind: scalarInteger, raw: b.votedAtRaw},
204		}, func(field, problem string) error {
205			return fmt.Errorf("voting proposal %q ballot %d field %q %s", id, index, field, problem)
206		})
207	}
208	
209	// storedTally 是已保存的首次计票结果。只要提案有计票结果，for_weight 与
210	// against_weight 就必须各自明确写出：即使某一侧（或两侧）的实际票重为零，
211	// 也不得靠零值/默认值补出治理记录——缺失或 null 的 for_weight 不得被当作 0
212	// 赞成，缺失或 null 的 against_weight 不得被当作 0 反对。
213	//
214	// 两个权重字段先用 RawMessage 接住，使“字段缺失”与“显式 null/写错类型”在解码后
215	// 仍可区分：encoding/json 直接解进 int64 时会把这三种情况都折叠成 0，恰好与
216	// “该侧没有票”的合法零权重无法区分。每个字段的“缺失/空值/类型不符”由
217	// validateStoredTally 判定。
218	type storedTally struct {
219		ForWeight     int64 `json:"for_weight"`
220		AgainstWeight int64 `json:"against_weight"`
221		TalliedAt     int64 `json:"tallied_at"`
222	
223		forWeightRaw     json.RawMessage
224		againstWeightRaw json.RawMessage
225	}
226	
227	// tallyJSONShape 只用于解码，按保存格式的字段名逐字接住每个字段的原始 JSON。
228	type tallyJSONShape struct {
229		ForWeight     json.RawMessage `json:"for_weight"`
230		AgainstWeight json.RawMessage `json:"against_weight"`
231		TalliedAt     int64           `json:"tallied_at"`
232	}
233	
234	// UnmarshalJSON 保留两个权重字段是否出现及其原始写法（缺失为 nil、null 为
235	// "null"），供 validateStoredTally 区分缺失、空值与类型不符。单个字段类型不符时
236	// 这里不返回错误（对应治理字段保持零值），以免解码器在不含提案编号的通用错误处
237	// 提前失败；定位与判定统一交给 validateStoredTally。
238	func (t *storedTally) UnmarshalJSON(data []byte) error {
239		var shape tallyJSONShape
240		if err := json.Unmarshal(data, &shape); err != nil {
241			return err
242		}
243		t.forWeightRaw, t.againstWeightRaw = shape.ForWeight, shape.AgainstWeight
244		t.TalliedAt = shape.TalliedAt
245		// 仅当字段确实是 int64 整数时才填充治理字段；类型不符留待校验拒绝，
246		// 绝不能让错误类型悄悄落成 0 并参与查询或再次计票。
247		fillInt64(shape.ForWeight, &t.ForWeight)
248		fillInt64(shape.AgainstWeight, &t.AgainstWeight)
249		return nil
250	}
251	
252	// mustStoreTally 构造一份内存中的合法计票结果（首次计票路径使用）。
253	// 同步填上字段原始片段，使“提交前校验”与“打开重放校验”走同一份
254	// validateStoredTally 判定时不会把本进程新建的计票结果误判为字段缺失。
255	func mustStoreTally(forWeight, againstWeight, talliedAt int64) *storedTally {
256		forRaw, _ := json.Marshal(forWeight)
257		againstRaw, _ := json.Marshal(againstWeight)
258		return &storedTally{
259			ForWeight:        forWeight,
260			AgainstWeight:    againstWeight,
261			TalliedAt:        talliedAt,
262			forWeightRaw:     forRaw,
263			againstWeightRaw: againstRaw,
264		}
265	}
266	
267	// validateStoredTally 严格判定一份已保存计票结果的两个权重字段：
268	// for_weight 与 against_weight 任一未写出、显式为 null 或不是 int64 整数
269	// （字符串/小数/指数/超界）都返回带提案编号、字段名与原因的错误。
270	// 明确写出的 0 是合法权重（该侧没有票），不得当成缺失。
271	// “缺失/空值/类型不符”的判定与逐票明细、执行凭据共用同一份规则
272	// （validateRawFields），此处只补充计票记录的业务位置：提案编号 + tally 标识。
273	func validateStoredTally(id string, t *storedTally) error {
274		return validateRawFields([]rawField{
275			{name: "for_weight", kind: scalarInteger, raw: t.forWeightRaw},
276			{name: "against_weight", kind: scalarInteger, raw: t.againstWeightRaw},
277		}, func(field, problem string) error {
278			return fmt.Errorf("voting proposal %q tally field %q %s", id, field, problem)
279		})
280	}
281	
282	// storedVoteProposal 按成员提交顺序保存成员与委托（顺序不影响相等性），
283	// 动作文本与顺序原样保存（顺序影响相等性）。
284	type storedVoteProposal struct {
285		ID          string             `json:"id"`
286		State       string             `json:"state"`
287		Members     []storedMember     `json:"members"`
288		Delegations []storedDelegation `json:"delegations"`
289		Quorum      int64              `json:"quorum"`
290		StartAt     int64              `json:"start_at"`
291		Deadline    int64              `json:"deadline"`
292		TimelockEnd int64              `json:"timelock_end"`
293		Actions     []string           `json:"actions"`
294		Ballots     []storedBallot     `json:"ballots"`
295		Tally       *storedTally       `json:"tally,omitempty"`
296	}
297	
298	// ---- 校验与派生 ----
299	
300	type proposalSpec struct {
301		members  []VoteMember
302		weights  map[string]int64
303		delegate map[string]string // 直接委托对象
304		pathOf   map[string][]string
305		headOf   map[string]string // 最终代表
306		groupW   map[string]int64  // 最终代表名下归集的全部原始权重
307		total    int64
308	}
309	
310	// validateProposalInput 校验全部创建规则并派生委托路径与代表权重。
311	// 任何非法条件都返回错误，调用方必须整项拒绝。
312	func validateProposalInput(in *CreateVoteInput) (*proposalSpec, error) {
313		if in.ID == "" {
314			return nil, invalidProposal("proposal id must not be empty")
315		}
316		if len(in.Members) == 0 {
317			return nil, invalidProposal("proposal %s: member list must not be empty", in.ID)
318		}
319		weights := make(map[string]int64, len(in.Members))
320		order := make([]string, 0, len(in.Members))
321		for _, m := range in.Members {
322			if m.ID == "" {
323				return nil, invalidProposal("proposal %s: member id must not be empty", in.ID)
324			}
325			if _, dup := weights[m.ID]; dup {
326				return nil, invalidProposal("proposal %s: duplicate member %q", in.ID, m.ID)
327			}
328			if m.Weight <= 0 {
329				return nil, invalidProposal("proposal %s: member %q weight must be a positive integer, got %d", in.ID, m.ID, m.Weight)
330			}
331			weights[m.ID] = m.Weight
332			order = append(order, m.ID)
333		}
334	
335		// 总权重必须在 int64 范围内（各权重已为正）。
336		var total int64
337		for _, m := range in.Members {
338			sum, ok := addInt64(total, m.Weight)
339			if !ok {
340				return nil, invalidProposal("proposal %s: total member weight overflows int64", in.ID)
341			}
342			total = sum
343		}
344	
345		if in.Quorum < 1 || in.Quorum > total {
346			return nil, invalidProposal("proposal %s: quorum must be between 1 and total weight %d, got %d", in.ID, total, in.Quorum)
347		}
348		if !(0 <= in.StartAt && in.StartAt < in.Deadline && in.Deadline <= in.TimelockEnd) {
349			return nil, invalidProposal("proposal %s: times must satisfy 0 <= start < deadline <= timelock, got start=%d deadline=%d timelock=%d",
350				in.ID, in.StartAt, in.Deadline, in.TimelockEnd)
351		}
352	
353		delegate := make(map[string]string, len(in.Delegations))
354		for _, d := range in.Delegations {
355			if d.From == "" || d.To == "" {
356				return nil, invalidProposal("proposal %s: delegation members must not be empty", in.ID)
357			}
358			if _, ok := weights[d.From]; !ok {
359				return nil, invalidProposal("proposal %s: delegation from unknown member %q", in.ID, d.From)
360			}
361			if _, ok := weights[d.To]; !ok {
362				return nil, invalidProposal("proposal %s: delegation to unknown member %q", in.ID, d.To)
363			}
364			if d.From == d.To {
365				return nil, invalidProposal("proposal %s: member %q must not delegate to itself", in.ID, d.From)
366			}
367			if _, dup := delegate[d.From]; dup {
368				return nil, invalidProposal("proposal %s: member %q delegates more than once", in.ID, d.From)
369			}
370			delegate[d.From] = d.To
371		}
372	
373		// 解析每名成员的委托路径：从本人出发，沿直接委托对象逐次前行，
374		// 直到未再委托的最终代表。每个成员出度至多 1，且自委托/循环已被拦截，
375		// 所以该遍历必然终止。
376		// 命中已解析成员时必须拼接其“完整路径”（去掉与之重复的衔接点），
377		// 不能直接跳到它的最终代表，否则多跳链上的中间委托对象会丢失。
378		// 结果只依赖委托关系本身，与成员及委托参数的提交顺序无关。
379		pathOf := make(map[string][]string, len(weights))
380		headOf := make(map[string]string, len(weights))
381		for _, id := range order {
382			if _, done := headOf[id]; done {
383				continue
384			}
385			chain := []string{id}
386			onChain := map[string]int{id: 0}
387			cur := id
388			for {
389				next, has := delegate[cur]
390				if !has {
391					break // cur 即未再委托的最终代表
392				}
393				if pos, cyc := onChain[next]; cyc {
394					return nil, invalidProposal("proposal %s: delegation cycle involving %q", in.ID, chain[pos])
395				}
396				if resolved, ok := pathOf[next]; ok {
397					// 拼接已解析的完整后缀；resolved[0] == next，逐跳衔接且无重复成员。
398					chain = append(chain, resolved...)
399					cur = resolved[len(resolved)-1]
400					break
401				}
402				chain = append(chain, next)
403				onChain[next] = len(chain) - 1
404				cur = next
405			}
406			head := cur
407			// 链上每个成员的路径都是自身到 head 的后缀。命中已解析后缀时，
408			// 后缀成员均已登记，这里只补齐尚未解析的成员。
409			for i := 0; i < len(chain); i++ {
410				member := chain[i]
411				if _, ok := headOf[member]; !ok {
412					pathOf[member] = append([]string(nil), chain[i:]...)
413					headOf[member] = head
414				}
415			}
416		}
417	
418		// 归集每个最终代表名下的全部原始权重；子集和必然不超过总权重。
419		groupW := make(map[string]int64)
420		for _, id := range order {
421			head := headOf[id]
422			sum, ok := addInt64(groupW[head], weights[id])
423			if !ok {
424				return nil, invalidProposal("proposal %s: delegated weight for %q overflows int64", in.ID, head)
425			}
426			groupW[head] = sum
427		}
428	
429		return &proposalSpec{
430			members:  append([]VoteMember(nil), in.Members...),
431			weights:  weights,
432			delegate: delegate,
433			pathOf:   pathOf,
434			headOf:   headOf,
435			groupW:   groupW,
436			total:    total,
437		}, nil
438	}
