540	// ---- 计票规则（唯一实现，首次计票、打开校验、查询结论共用） ----
541	
542	// ballotCounts 是按逐票明细汇总出的两侧权重。参与量只统计最终代表
543	// 实际投出的票，未投成员的权重既不在 For 也不在 Against 中，
544	// 因而不会被计入 Turnout，更不能直接拿成员总权重充当参与量。
545	type ballotCounts struct {
546		forWeight     int64
547		againstWeight int64
548	}
549	
550	// turnout 返回参与权重（赞成与反对之和），ok 表示合计未溢出 int64。
551	// 两侧各自不超过合法成员总权重时合计必不溢出；此处仍显式检查，
552	// 使“总权重恰好为 math.MaxInt64”的合法提案也不依赖该前提。
553	func (c ballotCounts) turnout() (int64, bool) {
554		return addInt64(c.forWeight, c.againstWeight)
555	}
556	
557	// votePasses 是唯一的通过条件：参与权重达到法定人数（恰好达到也算）
558	// 且赞成严格多于反对。平票、无人投票或参与不足一律不通过。
559	// 通过比较法定人数剩余容量判断参与量，避免 for+against 上溢时回绕为负，
560	// 把已达标（乃至总权重恰好为 int64 上限）的提案误判为参与不足。
561	func votePasses(forWeight, againstWeight, quorum int64) bool {
562		if forWeight <= againstWeight {
563			return false // 平票或赞成更少都不通过；两侧非负，无票时同样落在这里
564		}
565		return forWeight >= quorum-againstWeight // 等价于 for+against >= quorum，且不做上溢加法
566	}
567	
568	// tallyVerdict 把通过条件映射为提案首次计票后的状态。
569	func tallyVerdict(passed bool) string {
570		if passed {
571			return "passed"
572		}
573		return "rejected"
574	}
575	
576	// countBallots 只按票据选择累加两侧权重，不做代表资格与票重核对
577	// （资格核对由 verifyBallots 负责）。任何一侧溢出 int64 都返回损坏错误。
578	func countBallots(ballots []storedBallot) (ballotCounts, error) {
579		var c ballotCounts
580		for _, b := range ballots {
581			if b.Support {
582				sum, ok := addInt64(c.forWeight, b.Weight)
583				if !ok {
584					return ballotCounts{}, errors.New("for-side ballot weights overflow int64")
585				}
586				c.forWeight = sum
587			} else {
588				sum, ok := addInt64(c.againstWeight, b.Weight)
589				if !ok {
590					return ballotCounts{}, errors.New("against-side ballot weights overflow int64")
591				}
592				c.againstWeight = sum
593			}
594		}
595		return c, nil
596	}
597	
598	// verifyBallots 依据成员名单与委托关系逐票核对并汇总：
599	// 代表必须是最终代表、不得重复、票重必须等于委托后归集到其名下的权重。
600	// 这些条件全部由打开状态文件时的严格校验保证，首次计票路径再核对一次，
601	// 使两条路径对“票重/代表是否可信”的判定使用同一份规则。
602	// 汇总只含实际投出的票；任一条件不符返回带具体原因的错误，
603	// 错误分类（ErrStateCorrupt）由调用方按自身路径统一包装。
604	func verifyBallots(id string, ballots []storedBallot, spec *proposalSpec) (ballotCounts, error) {
605		seen := map[string]bool{}
606		for i, b := range ballots {
607			if b.Representative == "" {
608				return ballotCounts{}, fmt.Errorf("proposal %s ballot %d has empty representative", id, i)
609			}
610			if spec.headOf[b.Representative] != b.Representative {
611				return ballotCounts{}, fmt.Errorf("proposal %s ballot %d: %q is not a final representative",
612					id, i, b.Representative)
613			}
614			if seen[b.Representative] {
615				return ballotCounts{}, fmt.Errorf("proposal %s has duplicate stored ballot for %q", id, b.Representative)
616			}
617			seen[b.Representative] = true
618			if b.Weight != spec.groupW[b.Representative] {
619				return ballotCounts{}, fmt.Errorf("proposal %s ballot weight for %q (%d) does not match roster delegation (%d)",
620					id, b.Representative, b.Weight, spec.groupW[b.Representative])
621			}
622		}
623		counts, err := countBallots(ballots)
624		if err != nil {
625			return ballotCounts{}, fmt.Errorf("proposal %s %v", id, err)
626		}
627		return counts, nil
628	}
629	
630	// CastVote 在一项投票提案上投票。调用方通过 now 提供当前时间。
631	// 只有最终代表本人可投赞成/反对票，每位代表一张票，票重为归集到其名下的
632	// 全部原始权重。相同选择的重试始终返回首次记录；改投报冲突。
633	// 首次投票只接受 start <= now < deadline；计票之后拒绝一切新票。
634	func (s *Store) CastVote(id, voter string, support bool, now int64) (*BallotView, error) {
635		if voter == "" {
636			return nil, voteReject("voter id must not be empty")
637		}
638		commit, err := s.begin()
639		if err != nil {
640			return nil, err
641		}
642		defer commit()
643	
644		state, err := s.loadLocked()
645		if err != nil {
646			return nil, err
647		}
648		p, ok := state.VoteProposals[id]
649		if !ok {
650			return nil, fmt.Errorf("%w: %s", ErrProposalNotFound, id)
651		}
652		spec, verr := specOf(p)
653		if verr != nil {
654			return nil, verr // 正常路径不会发生：打开与提交前均已严格校验
655		}
656		if _, member := spec.weights[voter]; !member {
657			return nil, voteReject(fmt.Sprintf("voter %q is not on the member roster of %s", voter, id))
658		}
659		if spec.headOf[voter] != voter {
660			return nil, voteReject(fmt.Sprintf("voter %q has delegated the vote to %q and may not vote directly", voter, spec.headOf[voter]))
661		}
662		// 已投过票：相同选择的重试始终返回首次记录（与时间窗口、是否已计票无关）；
663		// 改投另一选择报冲突，绝不静默覆盖。
664		for i := range p.Ballots {
665			if p.Ballots[i].Representative == voter {
666				if p.Ballots[i].Support != support {
667					return nil, fmt.Errorf("%w: representative %q already voted %s for %s; changing the vote is not allowed",
668						ErrProposalConflict, voter, voteChoice(p.Ballots[i].Support), id)
669				}
670				b := p.Ballots[i]
671				return &BallotView{Representative: b.Representative, Weight: b.Weight, Support: b.Support, VotedAt: b.VotedAt}, nil
672			}
673		}
674		if p.Tally != nil {
675			return nil, voteReject(fmt.Sprintf("proposal %s has already been tallied; voting is closed", id))
676		}
677		if now < p.StartAt || now >= p.Deadline {
678			return nil, voteReject(fmt.Sprintf("proposal %s is not open for voting at now=%d (start=%d deadline=%d)", id, now, p.StartAt, p.Deadline))
679		}
680	
681		p.Ballots = append(p.Ballots, mustStoreBallot(voter, spec.groupW[voter], support, now))
682		if err := s.commitLocked(state); err != nil {
683			return nil, err
684		}
685		return &BallotView{Representative: voter, Weight: spec.groupW[voter], Support: support, VotedAt: now}, nil
686	}
687	
688	func voteChoice(support bool) string {
689		if support {
690			return "for"
691		}
692		return "against"
693	}
694	
695	// TallyVote 在截止时刻或之后进行首次计票：赞成与反对权重之和达到法定人数，
696	// 且赞成严格多于反对才通过。未投权重不计入参与量。
697	// 计票只确定状态，不转账；再次计票始终返回首次结论。
698	func (s *Store) TallyVote(id string, now int64) (*TallyResultView, error) {
699		commit, err := s.begin()
700		if err != nil {
701			return nil, err
702		}
703		defer commit()
704	
705		state, err := s.loadLocked()
706		if err != nil {
707			return nil, err
708		}
709		p, ok := state.VoteProposals[id]
710		if !ok {
711			return nil, fmt.Errorf("%w: %s", ErrProposalNotFound, id)
712		}
713		if p.Tally != nil {
714			return storedTallyResult(p), nil
715		}
716		if now < p.Deadline {
717			return nil, tallyReject(fmt.Sprintf("voting for %s is still open: now=%d deadline=%d", id, now, p.Deadline))
718		}
719	
720		spec, verr := specOf(p)
721		if verr != nil {
722			return nil, verr
723		}
724		// 计票规则只有一份：同一套“代表资格 + 票重 + 两侧汇总 + 法定人数/多数”
725		// 同时用于首次计票、打开文件时的重放校验与查询结论。
726		counts, verr := verifyBallots(id, p.Ballots, spec)
727		if verr != nil {
728			return nil, fmt.Errorf("%w: %v", ErrStateCorrupt, verr)
729		}
730		passed := votePasses(counts.forWeight, counts.againstWeight, p.Quorum)
731		p.Tally = mustStoreTally(counts.forWeight, counts.againstWeight, now)
732		p.State = tallyVerdict(passed)
733		if err := s.commitLocked(state); err != nil {
734			return nil, err
735		}
736		return storedTallyResult(p), nil
737	}
738	
739	// storedTallyResult 从已存储提案重建首次计票结论；尚未计票时返回 nil。
740	// Passed 由唯一的通过规则（votePasses）按保存权重重算：提案后续执行
741	// （executed）不改变首次结论，查询结论与首次计票结论因此始终一致。
742	// 调用方持有的状态均经过 validateState，两侧合计必然不超过合法总权重。
743	func storedTallyResult(p *storedVoteProposal) *TallyResultView {
744		if p.Tally == nil {
745			return nil
746		}
747		c := ballotCounts{forWeight: p.Tally.ForWeight, againstWeight: p.Tally.AgainstWeight}
748		turnout, _ := c.turnout()
749		return &TallyResultView{
750			ForWeight:     c.forWeight,
751			AgainstWeight: c.againstWeight,
752			Turnout:       turnout,
753			Quorum:        p.Quorum,
754			Passed:        votePasses(c.forWeight, c.againstWeight, p.Quorum),
755			TalliedAt:     p.Tally.TalliedAt,
756		}
757	}
