759	// VoteProposal 按编号查询一项投票提案；不存在时 ok 为 false。
760	func (s *Store) VoteProposal(id string) (*VoteProposalView, bool, error) {
761		state, err := s.readState()
762		if err != nil {
763			return nil, false, err
764		}
765		p, ok := state.VoteProposals[id]
766		if !ok {
767			return nil, false, nil
768		}
769		return voteProposalView(p), true, nil
770	}
