func TestPathSpellingsShareLock(t *testing.T) {
	dir := t.TempDir()
	cwd, err := os.Getwd()
	if err != nil {
		t.Fatal(err)
	}
	if err := os.Chdir(dir); err != nil {
		t.Fatal(err)
	}
	defer os.Chdir(cwd)

	// 相对拼写初始化。
	store, err := InitTreasury("treasury.json", 10)
	if err != nil {
		t.Fatal(err)
	}
