1	// Command govflow is the DAO 治理提案与执行平台 entry point.
2	package main
3	
4	import (
5		"encoding/json"
6		"flag"
7		"fmt"
8		"io"
9		"os"
10		"sort"
11		"strconv"
12		"strings"
13	
14		"github.com/gzhysuiioo/govflow-proposals/govflow"
15	)
16	
17	const versionText = "govflow 0.2.0"
18	
19	func main() {
20		command := "demo"
21		if len(os.Args) > 1 {
22			command = os.Args[1]
23		}
24		args := os.Args[2:]
25		switch command {
26		case "demo":
27			runDemo()
28		case "version":
29			fmt.Println(versionText)
30		case "help", "-h", "--help":
31			usage()
32		case "init":
33			runInit(args)
34		case "register":
35			runRegister(args)
36		case "create-vote":
37			runCreateVote(args)
38		case "vote":
39			runVote(args)
40		case "tally":
41			runTally(args)
42		case "execute":
43			runExecute(args)
44		case "balances":
45			runBalances(args)
46		case "proposal":
47			runProposal(args)
48		case "proposals":
49			runProposals(args)
50		case "receipt":
51			runReceipt(args)
52		case "receipts":
53			runReceipts(args)
54		default:
55			fmt.Fprintf(os.Stderr, "unknown command %q\n", command)
56			usage()
57			os.Exit(2)
58		}
59	}
60	
61	func usage() {
62		fmt.Println(`usage: govflow <command> [flags]
63	
64	legacy commands:
65	  demo                         run the built-in voting demo
66	  version                      print the version
67	
68	local treasury commands:
69	  init       --state FILE --balance N
70	             create a new state file with the initial treasury balance
71	  register   --state FILE --id ID --timelock N --action A [--action A ...]
72	             register a passed proposal (idempotent; conflicting content errors)
73	  create-vote --state FILE --id ID --member ID:W [--member ID:W ...]
74	             [--delegate FROM:TO ...] --quorum N --start N --deadline N
75	             --timelock N [--action A ...]
76	             create a voting proposal with roster, weights, delegations and a
77	             voting window (idempotent on identical content; conflict otherwise)
78	  vote       --state FILE --id ID --voter M --choice for|against --now N
79	             cast one ballot as a final representative (repeat same choice is
80	             idempotent; changing choice errors)
81	  tally      --state FILE --id ID --now N
82	             tally a proposal at/after its deadline; repeat calls return the
83	             first result
84	  execute    --state FILE --id ID --now N
85	             execute a passed proposal whose timelock has elapsed
86	             (works for both registered and voted proposals)
87	  balances   --state FILE [--account ACCT]
88	             show treasury and recipient account balances
89	  proposal   --state FILE --id ID
90	             show one registered proposal
91	  proposals  --state FILE
92	             list all registered proposals by id
93	  receipt    --state FILE --id ID
94	             show the execution receipt of one proposal
95	  receipts   --state FILE
96	             list all receipts in the order they were successfully committed
97	
98	all treasury commands accept --json for machine-readable output.`)
99	}
100	
101	// fail prints a domain error to stderr and exits 1; usage errors exit 2.
102	func fail(err error) {
103		fmt.Fprintf(os.Stderr, "error: %v\n", err)
104		os.Exit(1)
105	}
106	
107	type commonFlags struct {
108		state  string
109		asJSON bool
110		fs     *flag.FlagSet
111	}
112	
113	func newCmdFlags(name string) *commonFlags {
114		fs := flag.NewFlagSet(name, flag.ContinueOnError)
115		fs.SetOutput(io.Discard)
116		cf := &commonFlags{fs: fs}
117		fs.StringVar(&cf.state, "state", "", "path to the local treasury state file")
118		fs.BoolVar(&cf.asJSON, "json", false, "emit machine-readable JSON")
119		return cf
120	}
121	
122	func (c *commonFlags) parse(args []string) {
123		if err := c.fs.Parse(args); err != nil {
124			fmt.Fprintf(os.Stderr, "usage error: %v\n", err)
125			c.fs.SetOutput(os.Stderr)
126			c.fs.Usage()
127			os.Exit(2)
128		}
129		if c.state == "" {
130			fmt.Fprintf(os.Stderr, "usage error: --state is required\n")
131			os.Exit(2)
132		}
133	}
134	
135	func emitJSON(v any) {
136		raw, err := json.MarshalIndent(v, "", "  ")
137		if err != nil {
138			fail(err)
139		}
140		fmt.Println(string(raw))
141	}
142	
143	func parseIntFlag(fs *flag.FlagSet, name, raw string) int64 {
144		if raw == "" {
145			fmt.Fprintf(os.Stderr, "usage error: --%s is required\n", name)
146			os.Exit(2)
147		}
148		value, err := strconv.ParseInt(raw, 10, 64)
149		if err != nil {
150			fmt.Fprintf(os.Stderr, "usage error: --%s must be an int64: %v\n", name, err)
151			os.Exit(2)
152		}
153		return value
154	}
155	
156	// actionList 收集重复出现的 --action 参数，保持登记顺序。
157	type actionList []string
158	
159	func (a *actionList) String() string { return fmt.Sprint([]string(*a)) }
160	func (a *actionList) Set(v string) error {
161		*a = append(*a, v)
162		return nil
163	}
164	
165	func runInit(args []string) {
166		cf := newCmdFlags("init")
167		balanceRaw := cf.fs.String("balance", "", "initial treasury balance (non-negative int64)")
168		cf.parse(args)
169		balance := parseIntFlag(cf.fs, "balance", *balanceRaw)
170	
171		store, err := govflow.InitTreasury(cf.state, balance)
172		if err != nil {
173			fail(err)
174		}
175		defer store.Close()
176		if cf.asJSON {
177			emitJSON(map[string]any{"state": cf.state, "treasury": balance, "initialized": true})
178			return
179		}
180		fmt.Printf("initialized %s with treasury balance %d\n", cf.state, balance)
181	}
182	
183	func runRegister(args []string) {
184		cf := newCmdFlags("register")
185		id := cf.fs.String("id", "", "proposal id (non-empty)")
186		timelockRaw := cf.fs.String("timelock", "", "timelock end timestamp (int64)")
187		var actions actionList
188		cf.fs.Var(&actions, "action", "action text transfer:<account>:<amount> (repeatable, order preserved)")
189		cf.parse(args)
190		if *id == "" {
191			fmt.Fprintf(os.Stderr, "usage error: --id is required\n")
192			os.Exit(2)
193		}
194		timelock := parseIntFlag(cf.fs, "timelock", *timelockRaw)
195	
196		store, err := govflow.Open(cf.state)
197		if err != nil {
198			fail(err)
199		}
200		defer store.Close()
201		existed, err := store.Register(*id, timelock, []string(actions))
202		if err != nil {
203			fail(err)
204		}
205		if cf.asJSON {
206			emitJSON(map[string]any{"id": *id, "state": "passed", "timelock_end": timelock,
207				"actions": []string(actions), "already_registered": existed})
208			return
209		}
210		if existed {
211			fmt.Printf("proposal %s already registered with identical content\n", *id)
212		} else {
213			fmt.Printf("registered passed proposal %s (%d action(s), timelock_end=%d)\n", *id, len(actions), timelock)
214		}
215	}
216	
217	// memberList 收集重复的 --member ID:WEIGHT 参数，保持提交顺序。
218	type memberList []govflow.VoteMember
219	
220	func (m *memberList) String() string { return fmt.Sprint([]govflow.VoteMember(*m)) }
221	func (m *memberList) Set(v string) error {
222		id, weight, err := splitMember(v)
223		if err != nil {
224			return err
225		}
226		*m = append(*m, govflow.VoteMember{ID: id, Weight: weight})
227		return nil
228	}
229	
230	func splitMember(raw string) (string, int64, error) {
231		idx := strings.LastIndex(raw, ":")
232		if idx <= 0 || idx == len(raw)-1 {
233			return "", 0, fmt.Errorf("malformed member %q, expected ID:WEIGHT", raw)
234		}
235		id := raw[:idx]
236		weight, err := strconv.ParseInt(raw[idx+1:], 10, 64)
237		if err != nil {
238			return "", 0, fmt.Errorf("malformed member %q: weight must be int64: %v", raw, err)
239		}
240		return id, weight, nil
241	}
242	
243	// delegationList 收集重复的 --delegate FROM:TO 参数，保持提交顺序。
244	type delegationList []govflow.Delegation
245	
246	func (d *delegationList) String() string { return fmt.Sprint([]govflow.Delegation(*d)) }
247	func (d *delegationList) Set(v string) error {
248		from, to, ok := strings.Cut(v, ":")
249		if !ok || from == "" || to == "" {
250			return fmt.Errorf("malformed delegation %q, expected FROM:TO", v)
251		}
252		*d = append(*d, govflow.Delegation{From: from, To: to})
253		return nil
254	}
255	
256	func runCreateVote(args []string) {
257		cf := newCmdFlags("create-vote")
258		id := cf.fs.String("id", "", "proposal id (non-empty)")
259		var members memberList
260		cf.fs.Var(&members, "member", "member ID:WEIGHT with positive int64 weight (repeatable, order irrelevant to equality)")
261		var delegations delegationList
262		cf.fs.Var(&delegations, "delegate", "delegation FROM:TO (repeatable, order irrelevant to equality)")
263		quorumRaw := cf.fs.String("quorum", "", "required turnout weight between 1 and total member weight")
264		startRaw := cf.fs.String("start", "", "voting start timestamp (int64, >= 0)")
265		deadlineRaw := cf.fs.String("deadline", "", "voting deadline timestamp (int64, > start)")
266		timelockRaw := cf.fs.String("timelock", "", "timelock end timestamp (int64, >= deadline)")
267		var actions actionList
268		cf.fs.Var(&actions, "action", "action text transfer:<account>:<amount> (repeatable, order preserved)")
269		cf.parse(args)
270		if *id == "" {
271			fmt.Fprintf(os.Stderr, "usage error: --id is required\n")
272			os.Exit(2)
273		}
274		quorum := parseIntFlag(cf.fs, "quorum", *quorumRaw)
275		start := parseIntFlag(cf.fs, "start", *startRaw)
276		deadline := parseIntFlag(cf.fs, "deadline", *deadlineRaw)
277		timelock := parseIntFlag(cf.fs, "timelock", *timelockRaw)
278		if len(members) == 0 {
279			fmt.Fprintf(os.Stderr, "usage error: at least one --member ID:WEIGHT is required\n")
280			os.Exit(2)
281		}
282	
283		store, err := govflow.Open(cf.state)
284		if err != nil {
285			fail(err)
286		}
287		defer store.Close()
288		in := &govflow.CreateVoteInput{
289			ID:          *id,
290			Members:     []govflow.VoteMember(members),
291			Delegations: []govflow.Delegation(delegations),
292			Quorum:      quorum,
293			StartAt:     start,
294			Deadline:    deadline,
295			TimelockEnd: timelock,
296			Actions:     []string(actions),
297		}
298		view, existed, err := store.CreateVoteProposal(in)
299		if err != nil {
300			fail(err)
301		}
302		if cf.asJSON {
303			emitJSON(map[string]any{"proposal": view, "already_exists": existed})
304			return
305		}
306		if existed {
307			fmt.Printf("voting proposal %s already exists with identical content (state=%s)\n", view.ID, view.State)
308		} else {
309			fmt.Printf("created voting proposal %s: %d member(s), total_weight=%d, quorum=%d, voting=[%d,%d), timelock_end=%d, %d action(s)\n",
310				view.ID, len(view.Members), view.TotalWeight, view.Quorum, view.StartAt, view.Deadline, view.TimelockEnd, len(view.Actions))
311		}
312	}
313	
314	func runVote(args []string) {
315		cf := newCmdFlags("vote")
316		id := cf.fs.String("id", "", "proposal id to vote on")
317		voter := cf.fs.String("voter", "", "voting member (must be a final representative)")
318		choice := cf.fs.String("choice", "", "vote choice: for or against")
319		nowRaw := cf.fs.String("now", "", "current timestamp provided by the caller (int64)")
320		cf.parse(args)
321		if *id == "" || *voter == "" {
322			fmt.Fprintf(os.Stderr, "usage error: --id and --voter are required\n")
323			os.Exit(2)
324		}
325		var support bool
326		switch *choice {
327		case "for":
328			support = true
329		case "against":
330			support = false
331		default:
332			fmt.Fprintf(os.Stderr, "usage error: --choice must be %q or %q\n", "for", "against")
333			os.Exit(2)
334		}
335		now := parseIntFlag(cf.fs, "now", *nowRaw)
336	
337		store, err := govflow.Open(cf.state)
338		if err != nil {
339			fail(err)
340		}
341		defer store.Close()
342		ballot, err := store.CastVote(*id, *voter, support, now)
343		if err != nil {
344			fail(err)
345		}
346		if cf.asJSON {
347			emitJSON(ballot)
348			return
349		}
350		fmt.Printf("recorded vote proposal=%s representative=%s choice=%s weight=%d voted_at=%d\n",
351			*id, ballot.Representative, choiceWord(ballot.Support), ballot.Weight, ballot.VotedAt)
352	}
353	
354	func choiceWord(support bool) string {
355		if support {
356			return "for"
357		}
358		return "against"
359	}
360	
361	func runTally(args []string) {
362		cf := newCmdFlags("tally")
363		id := cf.fs.String("id", "", "proposal id to tally")
364		nowRaw := cf.fs.String("now", "", "current timestamp provided by the caller (int64, >= deadline)")
365		cf.parse(args)
366		if *id == "" {
367			fmt.Fprintf(os.Stderr, "usage error: --id is required\n")
368			os.Exit(2)
369		}
370		now := parseIntFlag(cf.fs, "now", *nowRaw)
371	
372		store, err := govflow.Open(cf.state)
373		if err != nil {
374			fail(err)
375		}
376		defer store.Close()
377		result, err := store.TallyVote(*id, now)
378		if err != nil {
379			fail(err)
380		}
381		if cf.asJSON {
382			emitJSON(map[string]any{"id": *id, "result": result})
383			return
384		}
385		verdict := "rejected"
386		if result.Passed {
387			verdict = "passed"
388		}
389		fmt.Printf("tally proposal=%s for=%d against=%d turnout=%d quorum=%d => %s (tallied_at=%d)\n",
390			*id, result.ForWeight, result.AgainstWeight, result.Turnout, result.Quorum, verdict, result.TalliedAt)
391	}
392	
393	func runExecute(args []string) {
394		cf := newCmdFlags("execute")
395		id := cf.fs.String("id", "", "proposal id to execute")
396		nowRaw := cf.fs.String("now", "", "current timestamp provided by the caller (int64)")
397		cf.parse(args)
398		if *id == "" {
399			fmt.Fprintf(os.Stderr, "usage error: --id is required\n")
400			os.Exit(2)
401		}
402		now := parseIntFlag(cf.fs, "now", *nowRaw)
403	
404		store, err := govflow.Open(cf.state)
405		if err != nil {
406			fail(err)
407		}
408		defer store.Close()
409		receipt, err := store.Execute(*id, now)
410		if err != nil {
411			fail(err)
412		}
413		if cf.asJSON {
414			emitJSON(receipt)
415			return
416		}
417		printReceiptText(receipt, false)
418	}
419	
420	func runBalances(args []string) {
421		cf := newCmdFlags("balances")
422		account := cf.fs.String("account", "", "show only this recipient account balance (unknown accounts are 0)")
423		cf.parse(args)
424		store, err := govflow.Open(cf.state)
425		if err != nil {
426			fail(err)
427		}
428		defer store.Close()
429		// 一次快照读取保证资金库与账户余额来自同一份已提交状态，
430		// 不会把并发执行前后的数字拼在一起。
431		snapshot, err := store.BalanceSnapshot()
432		if err != nil {
433			fail(err)
434		}
435		if *account != "" {
436			// 未出现过的账户余额为 0，且不向状态文件新增账户记录。
437			balance := snapshot.Balances[*account]
438			if cf.asJSON {
439				emitJSON(map[string]any{"treasury": snapshot.Treasury, "account": *account, "balance": balance})
440			} else {
441				fmt.Printf("treasury %d\n%s %d\n", snapshot.Treasury, *account, balance)
442			}
443			return
444		}
445		if cf.asJSON {
446			emitJSON(map[string]any{"treasury": snapshot.Treasury, "balances": snapshot.Balances})
447			return
448		}
449		fmt.Printf("treasury %d\n", snapshot.Treasury)
450		accounts := make([]string, 0, len(snapshot.Balances))
451		for acct := range snapshot.Balances {
452			accounts = append(accounts, acct)
453		}
454		sort.Strings(accounts)
455		for _, acct := range accounts {
456			fmt.Printf("%s %d\n", acct, snapshot.Balances[acct])
457		}
458	}
