105	// TestVerifyReceiptTransfersAcceptsPlannedAndRejectsTamper：执行预演产出的
106	// 逐笔结果构造的凭据必须被重放核对接受（两条路径同源）；篡改任一方的
107	// 前后余额都按既有原因与动作位置拒绝，且不推进重放状态。
108	func TestVerifyReceiptTransfersAcceptsPlannedAndRejectsTamper(t *testing.T) {
109		actions := []string{"transfer:audits:250", "transfer:audits:100", "transfer:legal:50"}
110		steps, _, _, err := planTransfers(actions, 1000, nil)
111		if err != nil {
112			t.Fatal(err)
113		}
114		good := &Receipt{ProposalID: "gip-1"}
115		for i, st := range steps {
116			good.Actions = append(good.Actions, st.actionReceipt(i, actions[i]))
117		}
118		balances := map[string]int64{}
119		treasury, err := verifyReceiptTransfers(good, actions, 1000, balances)
120		if err != nil {
121			t.Fatalf("planned receipt must verify: %v", err)
122		}
123		if treasury != 600 || balances["audits"] != 350 || balances["legal"] != 50 {
124			t.Fatalf("verify result treasury=%d balances=%+v", treasury, balances)
125		}
126	
127		// 重放路径的字段核对顺序：条数/编号/原文 → 资金库前 → 资金库后
128		// （不足在此）→ 收款前 → 收款后（溢出在此）。
129		cases := []struct {
130			name   string
131			tamper func(*ActionReceipt)
132			want   string
133		}{
134			{"treasury before", func(ar *ActionReceipt) { ar.Treasury.Before = 999 },
135				"action 1 treasury before-balance mismatch"},
136			{"treasury after", func(ar *ActionReceipt) { ar.Treasury.After = 651 },
137				"action 1 treasury after-balance mismatch"},
138			{"recipient before", func(ar *ActionReceipt) { ar.Recipient.Before = 249 },
139				"action 1 recipient before-balance mismatch"},
140			{"recipient after", func(ar *ActionReceipt) { ar.Recipient.After = 351 },
141				"action 1 recipient after-balance mismatch"},
142		}
143		for _, tc := range cases {
144			t.Run(tc.name, func(t *testing.T) {
145				bad := &Receipt{ProposalID: "gip-1"}
146				for i, st := range steps {
147					ar := st.actionReceipt(i, actions[i])
148					if i == 1 {
149						tc.tamper(&ar)
150					}
151					bad.Actions = append(bad.Actions, ar)
152				}
153				fresh := map[string]int64{}
154				start := int64(1000)
155				gotTreasury, err := verifyReceiptTransfers(bad, actions, start, fresh)
156				if err == nil || !strings.Contains(err.Error(), tc.want) {
157					t.Fatalf("tamper %s err=%v, want %q", tc.name, err, tc.want)
158				}
159				// 出错动作（第 1 笔）及其后动作不得应用：第 0 笔已核对的结果
160				// audits=250、资金库 750 保留，第 1 笔的 350 与 legal 的 50 不得出现。
161				if len(fresh) != 1 || fresh["audits"] != 250 {
162					t.Fatalf("failing action advanced replay state: %+v", fresh)
163				}
164				if gotTreasury != 750 {
165					t.Fatalf("treasury advanced past failing action: %d", gotTreasury)
166				}
167			})
168		}
169	
170		// 条数、编号、原文不一致沿用既有原因。
171		if _, err := verifyReceiptTransfers(good, actions[:2], 1000, map[string]int64{}); err == nil ||
172			!strings.Contains(err.Error(), "action count 3 does not match proposal 2") {
173			t.Fatalf("count mismatch err=%v", err)
174		}
175		renumbered := *good
176		renumbered.Actions = append([]ActionReceipt(nil), good.Actions...)
177		renumbered.Actions[2].Index = 9
178		if _, err := verifyReceiptTransfers(&renumbered, actions, 1000, map[string]int64{}); err == nil ||
179			!strings.Contains(err.Error(), `action 2 has index 9`) {
180			t.Fatalf("index mismatch err=%v", err)
181		}
182		differentText := append([]string(nil), actions...)
183		differentText[0] = "transfer:audits:251"
184		if _, err := verifyReceiptTransfers(good, differentText, 1000, map[string]int64{}); err == nil ||
185			!strings.Contains(err.Error(), "text does not match registered action") {
186			t.Fatalf("text mismatch err=%v", err)
187		}
188	
189		// 重放侧先核对资金库：一笔同时“资金不足”且“收款溢出”的动作，
190		// 读取路径先报告资金库一侧（与执行路径先报溢出各自保持不变）。
191		// 凭据把资金库后余额写成重算出的 -5（恰好等于 treasury-amount）：
192		// 若按首个失败原因推断会漏掉资金不足而落到收款侧，独立的不足标志
193		// 必须仍让资金库一侧先报错。
194		conflict := &Receipt{ProposalID: "gip-x", Actions: []ActionReceipt{{
195			Index: 0, Action: "transfer:a:10",
196			Treasury:  BalanceUpdate{Account: "treasury", Before: 5, After: -5},
197			Recipient: BalanceUpdate{Account: "a", Before: math.MaxInt64 - 5, After: math.MaxInt64},
198		}}}
199		_, err = verifyReceiptTransfers(conflict, []string{"transfer:a:10"}, 5, map[string]int64{})
200		if err == nil || !strings.Contains(err.Error(), "action 0 treasury after-balance mismatch") {
201			t.Fatalf("replay precedence err=%v, want treasury-side mismatch first", err)
202		}
203	}
