263	// TestTamperedReceiptBalancesRejectWithCause：凭据中资金库/收款账户的
264	// 前后余额被篡改时，整份状态判为损坏，错误沿用既有原因与动作位置，
265	// 原文件保持原样，不改成重算结果后继续提供查询。
266	func TestTamperedReceiptBalancesRejectWithCause(t *testing.T) {
267		dir := t.TempDir()
268		path := filepath.Join(dir, "treasury.json")
269		store, err := InitTreasury(path, 1000)
270		if err != nil {
271			t.Fatal(err)
272		}
273		mustRegister(t, store, "gip-1", 0,
274			"transfer:audits:250", "transfer:audits:100", "transfer:legal:50")
275		if _, err := store.Execute("gip-1", 0); err != nil {
276			t.Fatal(err)
277		}
278		store.Close()
279	
280		good, err := os.ReadFile(path)
281		if err != nil {
282			t.Fatal(err)
283		}
284		mutate := func(fn func(actions []any)) []byte {
285			var doc map[string]any
286			if err := json.Unmarshal(good, &doc); err != nil {
287				t.Fatal(err)
288			}
289			rcpt := doc["receipts"].([]any)[0].(map[string]any)
290			fn(rcpt["actions"].([]any))
291			raw, err := json.MarshalIndent(doc, "", "  ")
292			if err != nil {
293				t.Fatal(err)
294			}
295			return append(raw, '\n')
296		}
297		setField := func(actions []any, i int, side string, field string, value any) {
298			entry := actions[i].(map[string]any)[side].(map[string]any)
299			entry[field] = value
300		}
301		cases := []struct {
302			name string
303			raw  []byte
304			want string
305		}{
306			{"treasury-before", mutate(func(a []any) { setField(a, 1, "treasury", "before", 999) }),
307				"action 1 treasury before-balance mismatch"},
308			{"treasury-after", mutate(func(a []any) { setField(a, 1, "treasury", "after", 651) }),
309				"action 1 treasury after-balance mismatch"},
310			{"recipient-before", mutate(func(a []any) { setField(a, 1, "recipient", "before", 249) }),
311				"action 1 recipient before-balance mismatch"},
312			{"recipient-after", mutate(func(a []any) { setField(a, 1, "recipient", "after", 351) }),
313				"action 1 recipient after-balance mismatch"},
314			{"recipient-account", mutate(func(a []any) { setField(a, 0, "recipient", "account", "other") }),
315				"action 0 recipient before-balance mismatch"},
316			{"treasury-account", mutate(func(a []any) { setField(a, 0, "treasury", "account", "vault") }),
317				"action 0 treasury before-balance mismatch"},
318		}
319		for _, tc := range cases {
320			t.Run(tc.name, func(t *testing.T) {
321				bad := filepath.Join(dir, "tamper-"+tc.name+".json")
322				if err := os.WriteFile(bad, tc.raw, 0o600); err != nil {
323					t.Fatal(err)
324				}
325				s, err := Open(bad)
326				if !errors.Is(err, ErrStateCorrupt) {
327					if s != nil {
328						s.Close()
329					}
330					t.Fatalf("Open err=%v, want ErrStateCorrupt", err)
331				}
332				if !strings.Contains(err.Error(), tc.want) {
333					t.Fatalf("error %q missing %q", err.Error(), tc.want)
334				}
335				// 原文件保持原样，不被重算结果覆盖。
336				if got, rerr := os.ReadFile(bad); rerr != nil || string(got) != string(tc.raw) {
337					t.Fatalf("corrupt file was modified")
338				}
339			})
340		}
341	}
