343	// TestRegisteredAndVotedProposalsTransferIdentically：相同动作与起始余额下，
344	// 登记来源与投票通过来源的提案产生相同的资金变动与逐笔凭据，且已执行
345	// 提案再次执行仍返回首次凭据。
346	func TestRegisteredAndVotedProposalsTransferIdentically(t *testing.T) {
347		actions := []string{"transfer:audits:250", "transfer:audits:100", "transfer:legal:50"}
348	
349		registered, _ := openTempStore(t, 1000)
350		defer registered.Close()
351		mustRegister(t, registered, "gip-r", 0, actions...)
352		rr, err := registered.Execute("gip-r", 0)
353		if err != nil {
354			t.Fatal(err)
355		}
356	
357		voted, _ := openTempStore(t, 1000)
358		defer voted.Close()
359		in := baseVoteInput("gip-v")
360		in.Actions = actions
361		in.StartAt, in.Deadline, in.TimelockEnd = 0, 1, 1
362		mustCreateVote(t, voted, in)
363		if _, err := voted.CastVote("gip-v", "alice", true, 0); err != nil {
364			t.Fatal(err)
365		}
366		if _, err := voted.TallyVote("gip-v", 1); err != nil {
367			t.Fatal(err)
368		}
369		vr, err := voted.Execute("gip-v", 1)
370		if err != nil {
371			t.Fatal(err)
372		}
373	
374		if len(rr.Actions) != len(vr.Actions) {
375			t.Fatalf("receipt action counts differ: %d vs %d", len(rr.Actions), len(vr.Actions))
376		}
377		for i := range rr.Actions {
378			// 两个来源的凭据只有动作原文（编号相同）与双方前后余额可比。
379			ra, va := rr.Actions[i], vr.Actions[i]
380			if ra.Action != va.Action || !reflect.DeepEqual(ra.Treasury, va.Treasury) ||
381				!reflect.DeepEqual(ra.Recipient, va.Recipient) || ra.Index != va.Index {
382				t.Fatalf("action %d differs by source:\nregistered=%+v\nvoted=%+v", i, ra, va)
383			}
384		}
385		for _, pair := range []struct {
386			name    string
387			store   *Store
388			receipt *Receipt
389			id      string
390		}{
391			{"registered", registered, rr, "gip-r"},
392			{"voted", voted, vr, "gip-v"},
393		} {
394			if bal, _ := pair.store.TreasuryBalance(); bal != 600 {
395				t.Fatalf("%s treasury=%d, want 600", pair.name, bal)
396			}
397			if bal, _ := pair.store.Balance("audits"); bal != 350 {
398				t.Fatalf("%s audits=%d, want 350", pair.name, bal)
399			}
400			if bal, _ := pair.store.Balance("legal"); bal != 50 {
401				t.Fatalf("%s legal=%d, want 50", pair.name, bal)
402			}
403			// 再次执行返回首次凭据，不产生二次资金变动。
404			again, err := pair.store.Execute(pair.id, 99999)
405			if err != nil {
406				t.Fatalf("%s re-execute: %v", pair.name, err)
407			}
408			if again.Order != pair.receipt.Order || again.ExecutedAt != pair.receipt.ExecutedAt ||
409				!reflect.DeepEqual(again.Actions, pair.receipt.Actions) {
410				t.Fatalf("%s re-execute changed receipt:\nfirst=%+v\nagain=%+v", pair.name, pair.receipt, again)
411			}
412			if bal, _ := pair.store.TreasuryBalance(); bal != 600 {
413				t.Fatalf("%s treasury changed on retry: %d", pair.name, bal)
414			}
415		}
416	}
